71:     /**
72:      * @notice returns the price of a given token in USD (token:Usd Price)
73:      * @dev if ETH returns 1000 USD, this function returns 1000
74:      * (ignoring decimal precision)
75:      */
76:     function getTokenPrice(address token, uint256 lookback) internal view returns (uint256) {
77:         // oracles that are implmented within beanstalk should be placed here.
78:         if (token == C.WETH) {
79:             uint256 ethUsdPrice = LibEthUsdOracle.getEthUsdPrice(lookback);
80:             if (ethUsdPrice == 0) return 0;
81:             return ethUsdPrice;
82:         }
83:         if (token == C.WSTETH) {
84:             uint256 wstethUsdPrice = LibWstethUsdOracle.getWstethUsdPrice(0);
85:             if (wstethUsdPrice == 0) return 0;
86:             return wstethUsdPrice;
