94:     /**
95:      * @notice gets the token price from an external oracle.
96:      * @dev if address is 0, use the current contract.
97:      * If encodeType is 0x01, use the default chainlink implementation.
98:      * Returns 0 rather than reverting if the call fails.
99:      */
100:     function getTokenPriceFromExternal(
101:         address token,
102:         uint256 lookback
103:     ) internal view returns (uint256 tokenPrice) {
104:         AppStorage storage s = LibAppStorage.diamondStorage();
105:         Implementation memory oracleImpl = s.sys.oracleImplementation[token];
106: 
107:         // If the encode type is type 1, use the default chainlink implementation instead.
108:         // `target` refers to the address of the price aggergator implmenation
109:         if (oracleImpl.encodeType == bytes1(0x01)) {
110:             // if the address in the oracle implementation is 0, use the chainlink registry to lookup address
111:             address chainlinkOraclePriceAddress = oracleImpl.target;
112:             if (chainlinkOraclePriceAddress == address(0)) {
113:                 // use the chainlink registry
114:                 chainlinkOraclePriceAddress = ChainlinkPriceFeedRegistry(chainlinkRegistry).getFeed(
115:                         token,
